module fsm (
    input IN,
    input CLK,
    input RST,
    output MATCH
);
    reg [2:0] ST_cr, ST_nt;

    localparam s0 = 3'd0;
    localparam s1 = 3'd1;
    localparam s2 = 3'd2;
    localparam s3 = 3'd3;
    localparam s4 = 3'd4;
    localparam s5 = 3'd5;
    always @(posedge CLK or posedge RST) begin
        if(RST) begin
            ST_cr <= s0;
        end 
        else begin
            ST_cr <= ST_nt;
        end
    end

    always @(*) begin
        case(ST_cr)
            s0: begin
                if(IN==1) ST_nt=s1;
                else ST_nt=s0;
            end

            s1: begin
                if(IN==1) ST_nt=s1;
                else ST_nt=s2;
            end

            s2: begin
                if(IN==1) ST_nt=s1;
                else ST_nt=s3;
            end

            s3: begin
                if(IN==1) ST_nt=s4;
                else ST_nt=s0;
            end

            s4: begin
                if(IN==1) ST_nt=s5;
                else ST_nt=s2;
            end

            s5: begin
                if(IN==1) ST_nt=s1;
                else ST_nt=s2;
            end

            default: begin
                ST_nt=s0;
            end
        endcase
    end

    assign MATCH=(ST_cr==s4&&IN==1)?1:0;
endmodule
